(() => {
  "use strict";

  const API="https://jhjbiejqtbidloxcwryr.supabase.co/functions/v1/api";
  const PUBLISHABLE_KEY="sb_publishable_mA5DOfPA-ExloawT3aJpNw_2PeVgEEc";
  const ROOT=document.querySelector("#app");
  const TOKEN_KEY="crimescene-admin-token";
  const USER_KEY="crimescene-admin-user";
  const CUSTOMER_SITE="https://sosirusok.github.io/crimescene/";

  const reservationLabels={PENDING_PAYMENT:"접수 중",CONFIRMED:"예약 확정",COMPLETED:"이용 완료",CANCEL_REQUESTED:"취소 확인 중",CANCELED:"예약 취소",NO_SHOW:"미방문"};
  const paymentLabels={READY:"결제 대기",PAID:"결제 완료",FAILED:"결제 실패",REFUNDED:"환급 완료"};
  const inquiryLabels={NEW:"새 문의",IN_PROGRESS:"확인 중",ANSWERED:"답변 완료",CLOSED:"처리 완료"};
  const sourceLabels={ONLINE:"온라인 예약",ADMIN:"관리자 등록",PHONE:"전화 예약",WALK_IN:"현장 예약"};
  const roomLabels={AVAILABLE:"예약 가능",OPEN_RECRUITING:"오픈룸 모집 중",OPEN_PLAYABLE:"게임 진행 가능",FULL:"정원 마감",PRIVATE_BOOKED:"단독팀 예약",BLOCKED:"운영 중지"};
  const actionLabels={
    RESERVATION_CREATED:"고객 예약 등록",ADMIN_RESERVATION_CREATED:"관리자 예약 등록",ADMIN_RESERVATION_UPDATED:"예약 상태 변경",ADMIN_RESERVATION_DETAILS_UPDATED:"예약 정보 변경",
    CANCELED:"고객 예약 취소",CANCEL_REQUESTED:"고객 취소 요청",ADMIN_THEME_UPDATED:"테마 정보 변경",ADMIN_SLOT_STATUS_UPDATED:"회차 상태 변경",
    ADMIN_STORE_SETTINGS_UPDATED:"매장 설정 변경",BUSINESS_INFORMATION_UPDATED:"사업자 정보 변경",INQUIRY_CREATED:"고객 문의 접수",ADMIN_INQUIRY_UPDATED:"문의 처리 상태 변경",
  };

  const state={
    token:localStorage.getItem(TOKEN_KEY)||"",
    user:readJson(localStorage.getItem(USER_KEY)),
    data:null,
    view:"dashboard",
    reservationQuery:"",
    reservationTheme:"",
    reservationStatus:"",
    roomState:"",
    scheduleDate:koreaToday(),
    scheduleTheme:"A",
    selectedTheme:"A",
    modal:null,
  };

  const h=(value)=>String(value??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
  const money=(value)=>`${Number(value||0).toLocaleString("ko-KR")}원`;
  const digits=(value)=>String(value??"").replace(/\D/g,"");
  const hhmm=(value)=>String(value??"").slice(0,5);
  const iconMenu=`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="M4 7h16M4 12h16M4 17h16"/></svg>`;
  const iconClose=`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="m5 5 14 14M19 5 5 19"/></svg>`;
  const iconCheck=`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></svg>`;

  function readJson(value){try{return JSON.parse(value||"null");}catch{return null;}}
  function koreaToday(){return new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Seoul",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());}
  function formatDate(value){return value?new Intl.DateTimeFormat("ko-KR",{year:"numeric",month:"long",day:"numeric",weekday:"short"}).format(new Date(`${value}T12:00:00+09:00`)):"-";}
  function formatDateTime(value){return value?new Intl.DateTimeFormat("ko-KR",{timeZone:"Asia/Seoul",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"}).format(new Date(value)):"-";}
  function formatPhone(value){const n=digits(value).slice(0,11);return n.length<=3?n:n.length<=7?`${n.slice(0,3)}-${n.slice(3)}`:`${n.slice(0,3)}-${n.slice(3,7)}-${n.slice(7)}`;}
  function theme(id){return state.data?.themes?.find(x=>x.id===id);}
  function roomInfo(room={}){const name=room.state||"AVAILABLE",count=Number(room.bookedCount||0),capacity=Number(room.capacity||0),minimum=Number(room.minimumPlayers||4),remaining=Math.max(0,Number(room.remaining??capacity-count));return{name,count,capacity,minimum,remaining,label:roomLabels[name]||name,tone:name==="OPEN_RECRUITING"?"recruiting":name==="OPEN_PLAYABLE"||name==="FULL"?"playable":name==="AVAILABLE"?"available":"closed",detail:name==="OPEN_RECRUITING"?`${Math.max(0,minimum-count)}명 이상 더 모이면 진행 가능`:name==="OPEN_PLAYABLE"?`최소 인원 충족 · ${remaining}자리 남음`:name==="FULL"?"정원 마감":name==="PRIVATE_BOOKED"?"다른 팀 합류 불가":name==="BLOCKED"?"예약을 받지 않는 회차":"새 예약 가능"};}

  async function api(path,options={},admin=false,timeout=15000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(`${API}${path}`,{...options,cache:"no-store",signal:controller.signal,headers:{apikey:PUBLISHABLE_KEY,"Content-Type":"application/json",...(admin&&state.token?{Authorization:`Bearer ${state.token}`}:{}) ,...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.error||"요청을 처리하지 못했습니다.");error.status=response.status;throw error;}return data;}catch(error){if(error?.name==="AbortError")throw new Error("응답이 늦어지고 있습니다. 잠시 후 다시 시도해 주세요.");throw error;}finally{clearTimeout(timer);}}
  function notify(message,type=""){let host=document.querySelector(".admin-toast-host");if(!host){host=document.createElement("div");host.className="admin-toast-host";document.body.append(host);}const item=document.createElement("div");item.className=`admin-toast ${type}`;item.setAttribute("role","status");item.textContent=message;host.append(item);setTimeout(()=>item.remove(),4500);}
  function setSession(result){state.token=result.token;state.user=result.user;localStorage.setItem(TOKEN_KEY,result.token);localStorage.setItem(USER_KEY,JSON.stringify(result.user));}
  function clearSession(){state.token="";state.user=null;state.data=null;localStorage.removeItem(TOKEN_KEY);localStorage.removeItem(USER_KEY);}

  function loginPage(message=""){
    ROOT.innerHTML=`<main class="admin-login"><section><header><span>크라임씬플레이 서면1호점</span><h1>운영 관리</h1><p>예약, 오픈룸, 회차와 매장 정보를 한곳에서 관리합니다.</p></header><form id="admin-login-form"><label class="field"><span>관리자 암호키</span><input type="password" name="accessKey" autocomplete="current-password" autocapitalize="none" spellcheck="false" required autofocus></label>${message?`<p class="admin-form-error">${h(message)}</p>`:""}<button type="submit">관리 화면 열기</button></form><footer><a href="${CUSTOMER_SITE}">고객 사이트 보기</a><small>암호키 원문은 저장하지 않습니다.</small></footer></section></main>`;
    document.querySelector("#admin-login-form")?.addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector("button");button.disabled=true;button.textContent="확인 중";try{const result=await api("/admin/login",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(form)))});setSession(result);await loadDashboard();}catch(error){loginPage(error.message);}});
  }

  const navItems=[
    ["dashboard","오늘 운영","홈"],["openrooms","오픈룸","팀"],["reservations","예약 관리","예약"],["schedule","회차 관리","회차"],["themes","테마 관리","테마"],
    ["settings","매장 설정","설정"],["inquiries","문의 관리","문의"],["notices","공지 관리","공지"],["audit","변경 기록","기록"],["security","암호키 변경","보안"],
  ];

  function shell(content,title,description,actions=""){
    const metrics=state.data?.metrics||{};
    ROOT.innerHTML=`<div class="admin-app"><aside class="admin-sidebar"><a class="admin-brand" href="${CUSTOMER_SITE}"><b>CS</b><span>크라임씬플레이<br>서면1호점</span></a><nav>${navItems.map(([key,label,short])=>`<button type="button" data-view="${key}" class="${state.view===key?"is-active":""}"><span>${short}</span><strong>${label}</strong>${key==="openrooms"&&metrics.recruitingRooms?`<i>${metrics.recruitingRooms}</i>`:""}${key==="inquiries"&&metrics.newInquiries?`<i>${metrics.newInquiries}</i>`:""}</button>`).join("")}</nav><div class="admin-sidebar-status"><strong>운영 데이터 연결 정상</strong><small>마지막 새로고침 ${new Date().toLocaleTimeString("ko-KR",{hour:"2-digit",minute:"2-digit"})}</small></div></aside><div class="admin-main"><header class="admin-top"><button class="admin-menu" type="button" aria-label="메뉴 열기">${iconMenu}</button><div><span>${h(state.user?.displayName||"서면점 운영자")}</span><small>관리자</small></div><a href="${CUSTOMER_SITE}" target="_blank" rel="noreferrer">고객 사이트</a><button type="button" id="admin-logout">로그아웃</button></header><main class="admin-content"><header class="admin-heading"><div><p>크라임씬플레이 서면1호점</p><h1>${h(title)}</h1><span>${h(description)}</span></div><div>${actions}<button type="button" id="admin-refresh">새로고침</button></div></header><section id="admin-view">${content}</section></main></div><div class="admin-sidebar-backdrop"></div></div>`;
    bindShell();
  }
  function bindShell(){document.querySelectorAll("[data-view]").forEach(button=>button.addEventListener("click",()=>{state.view=button.dataset.view;renderCurrent();document.querySelector(".admin-app")?.classList.remove("menu-open");}));document.querySelector("#admin-logout")?.addEventListener("click",()=>{clearSession();loginPage();});document.querySelector("#admin-refresh")?.addEventListener("click",loadDashboard);document.querySelector(".admin-menu")?.addEventListener("click",()=>document.querySelector(".admin-app")?.classList.toggle("menu-open"));document.querySelector(".admin-sidebar-backdrop")?.addEventListener("click",()=>document.querySelector(".admin-app")?.classList.remove("menu-open"));}

  async function loadDashboard(){if(!state.token){loginPage();return;}ROOT.innerHTML=`<main class="admin-loading-page"><div><i></i><strong>운영 데이터를 불러오고 있습니다.</strong></div></main>`;try{state.data=await api("/admin/dashboard",{},true);if(!state.user)state.user={displayName:"서면점 운영자"};if(!state.data.themes?.some(x=>x.id===state.selectedTheme))state.selectedTheme=state.data.themes?.[0]?.id||"A";if(!state.data.themes?.some(x=>x.id===state.scheduleTheme))state.scheduleTheme=state.data.themes?.[0]?.id||"A";renderCurrent();}catch(error){if(error.status===401){clearSession();loginPage("로그인이 만료되었습니다. 암호키를 다시 입력해 주세요.");}else{ROOT.innerHTML=`<main class="admin-fatal"><div><h1>운영 데이터를 불러오지 못했습니다.</h1><p>${h(error.message)}</p><button type="button">다시 시도</button></div></main>`;ROOT.querySelector("button")?.addEventListener("click",loadDashboard);}}}
  function go(view){state.view=view;renderCurrent();}
  function metric(label,value,unit,note,tone=""){return `<article class="admin-metric ${tone}"><span>${h(label)}</span><strong>${h(value)}<small>${h(unit)}</small></strong><p>${h(note)}</p></article>`;}

  function dashboardView(){const d=state.data,m=d.metrics||{},today=koreaToday(),todayRows=(d.reservations||[]).filter(x=>x.play_date===today&&!['CANCELED','NO_SHOW'].includes(x.status)).sort((a,b)=>a.start_time.localeCompare(b.start_time)),rooms=(d.openRooms||[]).filter(x=>x.playDate>=today).slice(0,4);const content=`<div class="admin-metrics">${metric("오늘 예약",m.today||0,"건","오늘 이용 예정","primary")}${metric("모집 중 오픈룸",m.recruitingRooms||0,"개","최소 인원 미충족","warning")}${metric("진행 가능한 오픈룸",m.playableRooms||0,"개","4명 이상 모임","success")}${metric("활성 예약",m.active||0,"건","취소·미방문 제외")}${metric("결제 완료 금액",Number(m.revenue||0).toLocaleString("ko-KR"),"원","결제 완료 건 기준")}</div><div class="admin-grid-2"><section class="admin-panel"><header><div><span>오늘 일정</span><h2>${h(formatDate(today))}</h2></div><button type="button" data-go="schedule">회차 관리</button></header>${todayRows.length?`<div class="admin-today-list">${todayRows.map(row=>`<article><time>${h(row.start_time)}</time><div><strong>${h(row.theme_title)}</strong><span>${h(row.customer_name)} · ${row.party_size}명 · ${row.open_room?"오픈룸":"단독팀"}</span></div><b>${h(reservationLabels[row.status]||row.status)}</b></article>`).join("")}</div>`:`<p class="admin-empty">오늘 등록된 예약이 없습니다.</p>`}</section><section class="admin-panel"><header><div><span>먼저 확인할 항목</span><h2>오픈룸 현황</h2></div><button type="button" data-go="openrooms">전체 보기</button></header>${rooms.length?`<div class="admin-today-list">${rooms.map(room=>{const info=roomInfo(room);return `<article><time>${h(room.startTime)}</time><div><strong>${h(room.themeTitle)}</strong><span>${h(formatDate(room.playDate))} · ${room.teamCount}팀</span></div><b>${info.count}/${info.capacity}명</b></article>`;}).join("")}</div>`:`<p class="admin-empty">확인할 오픈룸이 없습니다.</p>`}</section></div><section class="admin-panel admin-quick"><header><div><span>빠른 작업</span><h2>자주 사용하는 기능</h2></div></header><div><button type="button" data-go="reservations"><b>예약 직접 등록·수정</b><span>전화 예약, 일정과 인원 변경</span></button><button type="button" data-go="schedule"><b>회차 열기·닫기</b><span>날짜별 회차 운영 관리</span></button><button type="button" data-go="themes"><b>테마와 시간대 수정</b><span>가격, 정원, 운영 시간 변경</span></button></div></section>`;shell(content,"오늘 운영","오늘 일정과 먼저 처리할 항목을 확인합니다.",`<button class="primary" type="button" id="quick-new-reservation">예약 직접 등록</button>`);document.querySelectorAll("[data-go]").forEach(button=>button.addEventListener("click",()=>go(button.dataset.go)));document.querySelector("#quick-new-reservation")?.addEventListener("click",()=>openReservationModal());}

  function openroomsView(){const rooms=(state.data.openRooms||[]).filter(room=>{if(state.roomState==="RECRUITING")return room.state==="OPEN_RECRUITING";if(state.roomState==="PLAYABLE")return room.state==="OPEN_PLAYABLE"||room.state==="FULL";return true;});const content=`<div class="admin-filterbar"><label><span>상태</span><select id="room-state"><option value="">전체 오픈룸</option><option value="RECRUITING" ${state.roomState==="RECRUITING"?"selected":""}>모집 중</option><option value="PLAYABLE" ${state.roomState==="PLAYABLE"?"selected":""}>진행 가능</option></select></label><strong>${rooms.length}개 회차</strong></div>${rooms.length?`<div class="admin-openroom-grid">${rooms.map(room=>{const info=roomInfo(room),percent=info.capacity?Math.min(100,info.count/info.capacity*100):0;return `<article class="admin-room ${info.tone}"><header><div><span>${h(info.label)}</span><h2>${h(room.themeTitle)}</h2><small>${h(formatDate(room.playDate))} · ${h(room.startTime)}</small></div><b>${info.count}/${info.capacity}명</b></header><div class="admin-room-progress"><i style="width:${percent}%"></i></div><p>${h(info.detail)} · 참여 ${room.teamCount}팀</p><div class="admin-team-list">${(room.teams||[]).map(team=>`<section><span>${team.teamNumber}</span><div><strong>${h(team.customerName)} · ${team.partySize}명</strong><small>${h(team.phone)} · ${h(sourceLabels[team.source]||team.source)} · ${h(reservationLabels[team.status]||team.status)}</small></div><button type="button" data-edit="${h(team.id)}">수정</button>${team.message?`<blockquote>${h(team.message)}</blockquote>`:""}${team.adminNote?`<blockquote>관리 메모: ${h(team.adminNote)}</blockquote>`:""}</section>`).join("")}</div></article>`;}).join("")}</div>`:`<p class="admin-empty">조건에 맞는 오픈룸이 없습니다.</p>`}`;shell(content,"오픈룸","회차별 현재 인원과 참여 팀을 확인합니다.");document.querySelector("#room-state")?.addEventListener("change",event=>{state.roomState=event.target.value;openroomsView();});bindEditButtons();}

  function filteredReservations(){const q=state.reservationQuery.trim().toLowerCase();return(state.data.reservations||[]).filter(row=>{const text=[row.customer_name,row.phone,row.theme_title,row.play_date,row.start_time,sourceLabels[row.source]||row.source].join(" ").toLowerCase();return(!q||text.includes(q))&&(!state.reservationTheme||row.theme_id===state.reservationTheme)&&(!state.reservationStatus||row.status===state.reservationStatus);});}
  function reservationCard(row){return `<article class="admin-card" data-reservation="${row.id}"><header><div><span>${h(sourceLabels[row.source]||row.source||"예약")}</span><h2>${h(row.theme_title)}</h2><small>${h(row.play_date)} · ${h(row.start_time)}</small></div><b>${h(reservationLabels[row.status]||row.status)}</b></header><div class="admin-card-body"><dl><div><dt>예약자</dt><dd>${h(row.customer_name)}</dd></div><div><dt>연락처</dt><dd>${h(row.phone)}</dd></div><div><dt>인원</dt><dd>${row.party_size}명 · ${row.open_room?"오픈룸":"단독팀"}</dd></div><div><dt>금액</dt><dd>${money(row.total_amount)}</dd></div></dl>${row.special_request?`<blockquote>고객 전달사항: ${h(row.special_request)}</blockquote>`:""}${row.admin_note?`<blockquote>관리 메모: ${h(row.admin_note)}</blockquote>`:""}<div class="admin-card-actions"><button type="button" data-edit="${row.id}">예약 정보 수정</button></div></div><footer><label><span>예약 상태</span><select data-field="status">${Object.entries(reservationLabels).map(([key,label])=>`<option value="${key}" ${row.status===key?"selected":""}>${label}</option>`).join("")}</select></label><label><span>결제 상태</span><select data-field="paymentStatus">${Object.entries(paymentLabels).map(([key,label])=>`<option value="${key}" ${row.payment_status===key?"selected":""}>${label}</option>`).join("")}</select></label><button type="button" data-save-status>상태 저장</button></footer></article>`;}
  function reservationsView(){const rows=filteredReservations();const content=`<div class="admin-filterbar"><label><span>검색</span><input id="reservation-query" value="${h(state.reservationQuery)}" placeholder="이름, 전화번호, 날짜, 테마"></label><label><span>테마</span><select id="reservation-theme"><option value="">전체 테마</option>${state.data.themes.map(t=>`<option value="${t.id}" ${state.reservationTheme===t.id?"selected":""}>${h(t.shortTitle)}</option>`).join("")}</select></label><label><span>예약 상태</span><select id="reservation-status"><option value="">전체 상태</option>${Object.entries(reservationLabels).map(([key,label])=>`<option value="${key}" ${state.reservationStatus===key?"selected":""}>${label}</option>`).join("")}</select></label><strong>${rows.length}건</strong></div>${rows.length?`<div class="admin-card-grid">${rows.map(reservationCard).join("")}</div>`:`<p class="admin-empty">조건에 맞는 예약이 없습니다.</p>`}`;shell(content,"예약 관리","예약을 직접 등록하고 일정, 인원, 연락처와 상태를 수정합니다.",`<button type="button" id="export-reservations">CSV 저장</button><button class="primary" type="button" id="new-reservation">예약 직접 등록</button>`);document.querySelector("#reservation-query")?.addEventListener("input",event=>{state.reservationQuery=event.target.value;clearTimeout(event.target._timer);event.target._timer=setTimeout(reservationsView,250);});document.querySelector("#reservation-theme")?.addEventListener("change",event=>{state.reservationTheme=event.target.value;reservationsView();});document.querySelector("#reservation-status")?.addEventListener("change",event=>{state.reservationStatus=event.target.value;reservationsView();});document.querySelector("#new-reservation")?.addEventListener("click",()=>openReservationModal());document.querySelector("#export-reservations")?.addEventListener("click",()=>exportReservations(rows));bindEditButtons();bindStatusButtons();}
  function bindEditButtons(){document.querySelectorAll("[data-edit]").forEach(button=>button.addEventListener("click",()=>{const row=state.data.reservations.find(x=>x.id===button.dataset.edit);if(row)openReservationModal(row);}));}
  function bindStatusButtons(){document.querySelectorAll("[data-save-status]").forEach(button=>button.addEventListener("click",async()=>{const card=button.closest("[data-reservation]"),row=state.data.reservations.find(x=>x.id===card.dataset.reservation);button.disabled=true;try{await api("/admin/reservations",{method:"PATCH",body:JSON.stringify({id:row.id,status:card.querySelector('[data-field="status"]').value,paymentStatus:card.querySelector('[data-field="paymentStatus"]').value})},true);notify("예약 상태를 저장했습니다.","success");await loadDashboard();}catch(error){notify(error.message,"error");button.disabled=false;}}));}
  function exportReservations(rows){const headers=["날짜","시간","테마","예약자","연락처","인원","예약 방식","예약 상태","결제 상태","금액","접수 경로","관리 메모"],lines=[headers,...rows.map(r=>[r.play_date,r.start_time,r.theme_title,r.customer_name,r.phone,r.party_size,r.open_room?"오픈룸":"단독팀",reservationLabels[r.status]||r.status,paymentLabels[r.payment_status]||r.payment_status,r.total_amount,sourceLabels[r.source]||r.source,r.admin_note||""])];const csv="\ufeff"+lines.map(row=>row.map(value=>`"${String(value??"").replaceAll('"','""')}"`).join(",")).join("\r\n"),blob=new Blob([csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`크라임씬_예약_${koreaToday()}.csv`;a.click();URL.revokeObjectURL(url);}

  function scheduleView(){const t=theme(state.scheduleTheme),slots=(state.data.slots||[]).filter(x=>x.themeId===state.scheduleTheme&&x.playDate===state.scheduleDate);const byTime=new Map(slots.map(x=>[x.startTime,x]));const content=`<div class="admin-filterbar"><label><span>운영 날짜</span><input type="date" id="schedule-date" value="${h(state.scheduleDate)}"></label><label><span>테마</span><select id="schedule-theme">${state.data.themes.map(x=>`<option value="${x.id}" ${state.scheduleTheme===x.id?"selected":""}>${h(x.shortTitle)}</option>`).join("")}</select></label></div><section class="admin-schedule-head"><div><span>${h(formatDate(state.scheduleDate))}</span><h2>${h(t?.shortTitle||"")}</h2><p>예약이 있는 회차는 실수로 운영 중지할 수 없습니다.</p></div><div><button type="button" data-bulk="OPEN">전체 운영</button><button type="button" data-bulk="BLOCKED">전체 중지</button></div></section><div class="admin-slot-grid">${(t?.times||[]).map(time=>{const slot=byTime.get(time)||{state:"AVAILABLE",bookedCount:0,capacity:t.totalCapacity,remaining:t.totalCapacity,minimumPlayers:t.minPlayers},info=roomInfo(slot);return `<article class="admin-slot ${info.tone}"><header><time>${h(time)}</time><span>${info.count}/${info.capacity}명</span></header><strong>${h(info.label)}</strong><p>${h(info.detail)}</p><footer><button type="button" data-slot="${h(time)}" data-status="OPEN">운영</button><button type="button" data-slot="${h(time)}" data-status="BLOCKED">중지</button></footer></article>`;}).join("")}</div>`;shell(content,"회차 관리","날짜와 테마를 선택해 각 회차의 예약 가능 여부를 관리합니다.");document.querySelector("#schedule-date")?.addEventListener("change",event=>{state.scheduleDate=event.target.value;scheduleView();});document.querySelector("#schedule-theme")?.addEventListener("change",event=>{state.scheduleTheme=event.target.value;scheduleView();});document.querySelectorAll("[data-slot]").forEach(button=>button.addEventListener("click",async()=>{button.disabled=true;try{await api("/admin/availability",{method:"PATCH",body:JSON.stringify({themeId:state.scheduleTheme,playDate:state.scheduleDate,startTime:button.dataset.slot,status:button.dataset.status})},true);notify("회차 상태를 변경했습니다.","success");await loadDashboard();}catch(error){notify(error.message,"error");button.disabled=false;}}));document.querySelectorAll("[data-bulk]").forEach(button=>button.addEventListener("click",async()=>{const label=button.dataset.bulk==="OPEN"?"모든 회차를 운영 상태로 바꾸시겠습니까?":"예약이 없는 모든 회차를 중지하시겠습니까?";if(!confirm(label))return;button.disabled=true;try{const result=await api("/admin/availability/bulk",{method:"POST",body:JSON.stringify({themeId:state.scheduleTheme,playDate:state.scheduleDate,status:button.dataset.bulk})},true);notify(`${result.changed}개 회차를 변경했습니다.${result.skipped?` 예약이 있는 ${result.skipped}개는 유지했습니다.`:""}`,"success");await loadDashboard();}catch(error){notify(error.message,"error");button.disabled=false;}}));}

  function themesView(){const current=theme(state.selectedTheme)||state.data.themes[0],times=Array.isArray(current.times)?current.times:[];const content=`<div class="admin-theme-tabs">${state.data.themes.map(t=>`<button type="button" data-theme-tab="${t.id}" class="${current.id===t.id?"is-active":""}"><span>EP.${t.episode}</span><strong>${h(t.shortTitle)}</strong><small>최소 ${t.minPlayers}명 · 최대 ${t.totalCapacity}명</small></button>`).join("")}</div><form id="theme-form" class="admin-form-layout"><section class="admin-form-section"><h2>기본 정보</h2><div class="admin-form-grid"><label><span>전체 제목</span><input name="title" value="${h(current.title)}" required></label><label><span>짧은 제목</span><input name="shortTitle" value="${h(current.shortTitle)}" required></label><label><span>에피소드 번호</span><input name="episode" type="number" min="1" value="${current.episode}" required></label><label><span>노출 상태</span><select name="status"><option value="ACTIVE" ${current.status==="ACTIVE"?"selected":""}>고객 사이트 노출</option><option value="HIDDEN" ${current.status==="HIDDEN"?"selected":""}>숨김</option><option value="ARCHIVED" ${current.status==="ARCHIVED"?"selected":""}>운영 종료</option></select></label><label class="wide"><span>한 줄 소개</span><input name="tagline" value="${h(current.tagline)}"></label><label class="wide"><span>사건 소개</span><textarea name="synopsis">${h(current.synopsis)}</textarea></label><label><span>이미지 경로</span><input name="image" value="${h(current.image)}"></label></div></section><div><section class="admin-form-section"><h2>가격과 정원</h2><div class="admin-form-grid compact"><label><span>1인 가격</span><input name="price" type="number" min="0" value="${current.price}" required></label><label><span>이용 시간(분)</span><input name="duration" type="number" min="30" value="${current.duration}" required></label><label><span>최소 진행 인원</span><input name="minPlayers" type="number" min="1" value="${current.minPlayers}" required></label><label><span>용의자 정원</span><input name="suspectCapacity" type="number" min="0" value="${current.suspectCapacity}" required></label><label><span>탐정 정원</span><input name="detectiveCapacity" type="number" min="0" value="${current.detectiveCapacity}" required></label><label><span>강조 색상</span><input name="accent" value="${h(current.accent||"#c84b42")}"></label></div></section><section class="admin-form-section"><h2>운영 시간대</h2><div class="time-chip-editor" id="time-chips">${times.map(time=>`<span class="time-chip" data-time="${h(time)}"><b>${h(time)}</b><button type="button" aria-label="${h(time)} 삭제">×</button></span>`).join("")}</div><div class="time-add"><input type="time" id="new-time"><button type="button" id="add-time">시간 추가</button></div><p>시간대를 삭제하면 예약이 없는 미래 회차만 정리됩니다. 예약이 있는 회차는 유지됩니다.</p></section></div><div class="admin-form-actions"><span id="theme-form-message">변경 내용은 저장 버튼을 누른 뒤 고객 사이트에 반영됩니다.</span><button type="submit">테마 정보 저장</button></div></form>`;shell(content,"테마 관리","제목, 가격, 정원과 시간대를 직접 수정합니다.");document.querySelectorAll("[data-theme-tab]").forEach(button=>button.addEventListener("click",()=>{state.selectedTheme=button.dataset.themeTab;themesView();}));let editedTimes=[...times];function renderTimes(){const host=document.querySelector("#time-chips");host.innerHTML=editedTimes.map(time=>`<span class="time-chip" data-time="${h(time)}"><b>${h(time)}</b><button type="button" aria-label="${h(time)} 삭제">×</button></span>`).join("");host.querySelectorAll("button").forEach(button=>button.addEventListener("click",()=>{editedTimes=editedTimes.filter(x=>x!==button.closest("[data-time]").dataset.time);renderTimes();}));}renderTimes();document.querySelector("#add-time")?.addEventListener("click",()=>{const input=document.querySelector("#new-time"),value=input.value;if(value&&!editedTimes.includes(value)){editedTimes.push(value);editedTimes.sort();input.value="";renderTimes();}});document.querySelector("#theme-form")?.addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),message=document.querySelector("#theme-form-message"),values=Object.fromEntries(new FormData(form));if(!editedTimes.length){message.textContent="시간대를 한 개 이상 등록해 주세요.";message.className="error";return;}button.disabled=true;try{await api("/admin/themes",{method:"PATCH",body:JSON.stringify({...values,difficulty:"",id:current.id,times:editedTimes,episode:Number(values.episode),price:Number(values.price),duration:Number(values.duration),minPlayers:Number(values.minPlayers),suspectCapacity:Number(values.suspectCapacity),detectiveCapacity:Number(values.detectiveCapacity)})},true);notify("테마 정보를 저장했습니다.","success");await loadDashboard();}catch(error){message.textContent=error.message;message.className="error";button.disabled=false;}});}

  function settingsView(){const s=state.data.settings,p=state.data.payment;const content=`<form id="settings-form" class="admin-settings-form"><section class="admin-form-section"><h2>매장 기본 정보</h2><div class="admin-settings-grid"><label><span>고객 사이트 이름</span><input name="storeName" value="${h(s.storeName)}" required></label><label><span>지점명</span><input name="branchName" value="${h(s.branchName)}" required></label><label><span>사업자 상호</span><input value="(주)싱글" readonly aria-readonly="true"></label><label><span>대표자명</span><input name="representativeName" value="${h(s.representativeName)}"></label><label><span>사업자등록번호</span><input name="businessRegistrationNumber" value="${h(s.businessRegistrationNumber)}"></label><label><span>전화번호</span><input name="phone" value="${h(s.phone)}" required></label><label><span>이메일</span><input name="email" type="email" value="${h(s.email)}" required></label><label class="wide"><span>도로명 주소</span><input name="addressRoad" value="${h(s.addressRoad)}" required></label><label class="wide"><span>상세 주소</span><input name="addressDetail" value="${h(s.addressDetail)}"></label><label class="wide"><span>지도 검색 주소</span><input name="mapQuery" value="${h(s.mapQuery)}"></label></div></section><section class="admin-form-section"><h2>예약 운영 기준</h2><div class="admin-settings-grid"><label><span>예약 가능한 날짜 범위</span><input name="bookingWindowDays" type="number" min="1" max="60" value="${s.bookingWindowDays}" required></label><label><span>권장 도착 시간(분 전)</span><input name="arrivalMinutes" type="number" min="0" max="60" value="${s.arrivalMinutes}" required></label><label><span>온라인 취소 제한(시간 전)</span><input name="cancellationCutoffHours" type="number" min="0" max="336" value="${s.cancellationCutoffHours}" required></label><label><span>개인정보 담당자</span><input name="privacyOfficerName" value="${h(s.privacyOfficerName)}"></label><label class="wide"><span>개인정보 문의 연락처</span><input name="privacyOfficerContact" value="${h(s.privacyOfficerContact)}"></label><label class="wide"><span>고객 사이트 상단 안내</span><textarea name="customerNotice" maxlength="1000">${h(s.customerNotice||"")}</textarea></label></div></section><section class="admin-form-section"><h2>결제 운영</h2><div class="admin-settings-grid"><label><span>현재 결제 방식</span><select name="paymentMode"><option value="ONSITE" selected>방문 당일 매장 결제</option><option value="ONLINE" disabled>온라인 카드 결제 (연동 후 사용)</option></select></label><label><span>결제 대행사</span><input name="paymentProvider" value="${h(s.paymentProvider||"KISPG")}" readonly></label><label class="wide"><span>통신판매업 신고번호</span><input name="mailOrderRegistrationNumber" value="${h(s.mailOrderRegistrationNumber||"")}" placeholder="온라인 결제 사용 전에 입력"></label></div><label class="simple-check"><input type="checkbox" name="refundPolicyConfirmed" ${s.refundPolicyConfirmed?"checked":""}><span class="check-box">${iconCheck}</span><span>실제 매장 환불 기준을 확인하고 고객 안내 문구에 반영했습니다.</span></label><div class="payment-readiness"><header><div><span>현재 결제 방식</span><strong>방문 당일 매장 결제</strong></div><b>예약은 결제 연동 없이 바로 확정됩니다.</b></header><ul><li><span>온라인 카드 결제</span><b class="wait">연동 전</b></li><li><span>카드 승인·취소 모듈</span><b class="${p.integrationReady?"ok":"wait"}">${p.integrationReady?"연동 완료":"연동 필요"}</b></li><li><span>가맹점 연동 정보</span><b class="${p.configured?"ok":"wait"}">${p.configured?"등록 완료":"미등록"}</b></li><li><span>통신판매업 신고번호</span><b class="${s.mailOrderRegistrationNumber?"ok":"wait"}">${s.mailOrderRegistrationNumber?"입력 완료":"입력 필요"}</b></li><li><span>환불 기준 확인</span><b class="${s.refundPolicyConfirmed?"ok":"wait"}">${s.refundPolicyConfirmed?"확인 완료":"확인 필요"}</b></li></ul></div></section><div class="admin-form-actions"><span id="settings-message">매장 정보와 운영 기준은 고객 사이트에 바로 반영됩니다.</span><button type="submit">매장 설정 저장</button></div></form>`;shell(content,"매장 설정","주소, 연락처와 예약 기준을 관리합니다. 온라인 결제는 연동 작업 후 별도로 활성화됩니다.");document.querySelector("#settings-form")?.addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),message=document.querySelector("#settings-message"),values=Object.fromEntries(new FormData(form));button.disabled=true;try{await api("/admin/settings",{method:"PATCH",body:JSON.stringify({...values,bookingWindowDays:Number(values.bookingWindowDays),arrivalMinutes:Number(values.arrivalMinutes),cancellationCutoffHours:Number(values.cancellationCutoffHours),refundPolicyConfirmed:form.elements.refundPolicyConfirmed.checked})},true);notify("매장 설정을 저장했습니다.","success");await loadDashboard();}catch(error){message.textContent=error.message;message.className="error";button.disabled=false;}});}

  function inquiriesView(){const rows=state.data.inquiries||[];const content=rows.length?`<div class="admin-inquiry-list">${rows.map(row=>`<article class="admin-inquiry" data-inquiry="${row.id}"><header><div><span>${h(inquiryLabels[row.status]||row.status)}</span><h2>${h(row.subject)}</h2></div><time>${h(formatDateTime(row.created_at))}</time></header><dl><div><dt>이름</dt><dd>${h(row.customer_name)}</dd></div><div><dt>연락처</dt><dd>${h(row.phone)}</dd></div></dl><p>${h(row.content).replace(/\n/g,"<br>")}</p><textarea data-response placeholder="처리 메모 또는 답변 내용">${h(row.response||"")}</textarea><footer><select data-status>${Object.entries(inquiryLabels).map(([key,label])=>`<option value="${key}" ${row.status===key?"selected":""}>${label}</option>`).join("")}</select><button type="button" data-save-inquiry>저장</button></footer></article>`).join("")}</div>`:`<p class="admin-empty">접수된 문의가 없습니다.</p>`;shell(content,"문의 관리","고객 문의를 확인하고 처리 상태와 메모를 저장합니다.");document.querySelectorAll("[data-save-inquiry]").forEach(button=>button.addEventListener("click",async()=>{const card=button.closest("[data-inquiry]");button.disabled=true;try{await api("/admin/inquiries",{method:"PATCH",body:JSON.stringify({id:card.dataset.inquiry,status:card.querySelector("[data-status]").value,response:card.querySelector("[data-response]").value})},true);notify("문의 내용을 저장했습니다.","success");await loadDashboard();}catch(error){notify(error.message,"error");button.disabled=false;}}));}

  function noticesView(){const rows=state.data.notices||[];const content=`<div class="admin-notice-layout"><form id="notice-create" class="admin-notice-form"><h2>새 공지 등록</h2><label><span>제목</span><input name="title" maxlength="100" required></label><label><span>내용</span><textarea name="content" maxlength="4000" required></textarea></label><label class="simple-check"><input type="checkbox" name="pinned"><span class="check-box">${iconCheck}</span><span>중요 공지로 위에 고정</span></label><label class="simple-check"><input type="checkbox" name="published" checked><span class="check-box">${iconCheck}</span><span>고객 사이트에 바로 게시</span></label><button type="submit">공지 등록</button></form><div class="admin-notice-list">${rows.length?rows.map(row=>`<article class="admin-notice" data-notice="${row.id}"><header><span>${row.pinned?"중요 공지":"공지"}</span><time>${h(formatDateTime(row.created_at))}</time></header><input data-title value="${h(row.title)}"><textarea data-content>${h(row.content)}</textarea><footer><label><input type="checkbox" data-pinned ${row.pinned?"checked":""}> 위에 고정</label><label><input type="checkbox" data-published ${row.published?"checked":""}> 게시</label><button type="button" data-save-notice>저장</button><button type="button" class="danger" data-delete-notice>삭제</button></footer></article>`).join(""):`<p class="admin-empty">등록된 공지가 없습니다.</p>`}</div></div>`;shell(content,"공지 관리","고객 사이트에 표시할 공지를 등록하고 수정합니다.");document.querySelector("#notice-create")?.addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector("button"),values=Object.fromEntries(new FormData(form));button.disabled=true;try{await api("/admin/notices",{method:"POST",body:JSON.stringify({...values,pinned:form.elements.pinned.checked,published:form.elements.published.checked})},true);notify("공지를 등록했습니다.","success");await loadDashboard();}catch(error){notify(error.message,"error");button.disabled=false;}});document.querySelectorAll("[data-save-notice]").forEach(button=>button.addEventListener("click",async()=>{const card=button.closest("[data-notice]");button.disabled=true;try{await api("/admin/notices",{method:"PATCH",body:JSON.stringify({id:Number(card.dataset.notice),title:card.querySelector("[data-title]").value,content:card.querySelector("[data-content]").value,pinned:card.querySelector("[data-pinned]").checked,published:card.querySelector("[data-published]").checked})},true);notify("공지를 저장했습니다.","success");await loadDashboard();}catch(error){notify(error.message,"error");button.disabled=false;}}));document.querySelectorAll("[data-delete-notice]").forEach(button=>button.addEventListener("click",async()=>{const card=button.closest("[data-notice]");if(!confirm("이 공지를 삭제하시겠습니까?"))return;button.disabled=true;try{await api("/admin/notices",{method:"DELETE",body:JSON.stringify({id:Number(card.dataset.notice)})},true);notify("공지를 삭제했습니다.","success");await loadDashboard();}catch(error){notify(error.message,"error");button.disabled=false;}}));}

  function auditView(){const rows=state.data.auditLogs||[];const content=rows.length?`<div class="admin-audit-list">${rows.map(row=>`<article class="admin-audit"><time>${h(formatDateTime(row.created_at))}</time><div><strong>${h(actionLabels[row.action]||row.action)}</strong><span>${h(row.target_type)} · ${h(row.target_id)}</span></div><small>${h(row.actor)}</small></article>`).join("")}</div>`:`<p class="admin-empty">표시할 변경 기록이 없습니다.</p>`;shell(content,"변경 기록","예약과 운영 설정의 최근 변경 내역을 확인합니다.");}

  function securityView(){const p=state.data.payment,s=state.data.settings;const content=`<div class="admin-security-layout"><form id="password-form" class="admin-security-form"><h2>관리자 암호키 변경</h2><label><span>현재 암호키</span><input type="password" name="currentAccessKey" autocomplete="current-password" required></label><label><span>새 암호키</span><input type="password" name="nextAccessKey" minlength="12" autocomplete="new-password" required></label><label><span>새 암호키 확인</span><input type="password" name="confirmAccessKey" minlength="12" autocomplete="new-password" required></label><div id="password-message"></div><button type="submit">암호키 변경</button></form><aside class="admin-security-info"><h2>현재 보호 상태</h2><dl><div><dt>관리자 로그인</dt><dd>보호 중</dd></div><div><dt>고객 연락처</dt><dd>보호 저장</dd></div><div><dt>외부 직접 접근</dt><dd>차단</dd></div><div><dt>온라인 결제</dt><dd>${p.onlineEnabled?"사용 중":"미사용"}</dd></div><div><dt>예약 방식</dt><dd>${s.paymentMode==="ONSITE"?"매장 결제":"온라인 결제"}</dd></div></dl></aside></div>`;shell(content,"암호키 변경","관리 화면에 들어올 때 사용하는 암호키를 변경합니다.");document.querySelector("#password-form")?.addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,message=document.querySelector("#password-message"),values=Object.fromEntries(new FormData(form));if(values.nextAccessKey!==values.confirmAccessKey){message.innerHTML=`<p class="admin-form-error">새 암호키가 서로 다릅니다.</p>`;return;}const button=form.querySelector("button");button.disabled=true;try{await api("/admin/change-password",{method:"POST",body:JSON.stringify({currentAccessKey:values.currentAccessKey,nextAccessKey:values.nextAccessKey})},true);notify("암호키를 변경했습니다. 다시 로그인해 주세요.","success");clearSession();setTimeout(()=>loginPage(),800);}catch(error){message.innerHTML=`<p class="admin-form-error">${h(error.message)}</p>`;button.disabled=false;}});}

  function openReservationModal(row=null){const editing=Boolean(row),themes=state.data.themes,currentTheme=theme(row?.theme_id)||themes[0],date=row?.play_date||koreaToday(),time=row?.start_time||currentTheme.times?.[0]||"",source=row?.source||"PHONE";const backdrop=document.createElement("div");backdrop.className="admin-modal-backdrop";backdrop.innerHTML=`<section class="admin-modal"><header><h2>${editing?"예약 정보 수정":"예약 직접 등록"}</h2><button type="button" class="admin-modal-close" aria-label="닫기">${iconClose}</button></header><form id="reservation-modal-form"><div class="admin-form-grid"><label><span>테마</span><select name="themeId">${themes.map(t=>`<option value="${t.id}" ${currentTheme.id===t.id?"selected":""}>${h(t.shortTitle)}</option>`).join("")}</select></label><label><span>접수 경로</span><select name="source">${Object.entries(sourceLabels).filter(([key])=>key!=="ONLINE"||editing).map(([key,label])=>`<option value="${key}" ${source===key?"selected":""}>${label}</option>`).join("")}</select></label><label><span>날짜</span><input name="playDate" type="date" value="${h(date)}" required></label><label><span>시간</span><select name="startTime"></select></label><label><span>예약자 이름</span><input name="customerName" maxlength="20" value="${h(row?.customer_name||"")}" required></label><label><span>휴대폰 번호</span><input name="phone" inputmode="tel" maxlength="13" value="${h(row?.phone||"")}" required></label><label><span>인원</span><input name="partySize" type="number" min="1" max="20" value="${row?.party_size||4}" required></label><label class="simple-check"><input type="checkbox" name="openRoom" ${row?.open_room?"checked":""}><span class="check-box">${iconCheck}</span><span>오픈룸으로 등록</span></label><label class="wide"><span>오픈룸 소개 또는 고객 요청사항</span><textarea name="specialRequest" maxlength="300">${h(row?.special_request||"")}</textarea></label><label class="wide"><span>관리자 메모</span><textarea name="adminNote" maxlength="1000">${h(row?.admin_note||"")}</textarea></label></div><div id="reservation-modal-message"></div><footer><button type="button" class="admin-modal-cancel">취소</button><button type="submit" class="primary">${editing?"변경 내용 저장":"예약 등록"}</button></footer></form></section>`;document.body.append(backdrop);const form=backdrop.querySelector("form"),themeSelect=form.elements.themeId,timeSelect=form.elements.startTime,close=()=>backdrop.remove();function fillTimes(preferred=""){const t=theme(themeSelect.value);timeSelect.innerHTML=(t?.times||[]).map(x=>`<option value="${h(x)}" ${x===preferred?"selected":""}>${h(x)}</option>`).join("");}fillTimes(time);themeSelect.addEventListener("change",()=>fillTimes());form.elements.phone.addEventListener("input",event=>{event.target.value=formatPhone(event.target.value);});backdrop.querySelector(".admin-modal-close").addEventListener("click",close);backdrop.querySelector(".admin-modal-cancel").addEventListener("click",close);backdrop.addEventListener("click",event=>{if(event.target===backdrop)close();});form.addEventListener("submit",async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('[type="submit"]'),message=backdrop.querySelector("#reservation-modal-message"),values=Object.fromEntries(new FormData(form));button.disabled=true;try{const endpoint=editing?"/admin/reservations/details":"/admin/reservations",method=editing?"PATCH":"POST";await api(endpoint,{method,body:JSON.stringify({...values,id:row?.id,partySize:Number(values.partySize),openRoom:form.elements.openRoom.checked})},true);notify(editing?"예약 정보를 수정했습니다.":"예약을 등록했습니다.","success");close();await loadDashboard();}catch(error){message.innerHTML=`<p class="admin-form-error">${h(error.message)}</p>`;button.disabled=false;}});}

  function renderCurrent(){if(!state.data){loadDashboard();return;}if(state.view==="dashboard")dashboardView();else if(state.view==="openrooms")openroomsView();else if(state.view==="reservations")reservationsView();else if(state.view==="schedule")scheduleView();else if(state.view==="themes")themesView();else if(state.view==="settings")settingsView();else if(state.view==="inquiries")inquiriesView();else if(state.view==="notices")noticesView();else if(state.view==="audit")auditView();else if(state.view==="security")securityView();else{state.view="dashboard";dashboardView();}}

  async function boot(){document.documentElement.classList.add("admin-ui");if(!ROOT)return false;if(!state.token){loginPage();return true;}await loadDashboard();return true;}
  globalThis.__CRIMESCENE_ADMIN_READY__=boot().catch(error=>{console.error(error);if(ROOT)ROOT.innerHTML=`<main class="admin-fatal"><div><h1>관리 화면을 불러오지 못했습니다.</h1><p>${h(error.message)}</p><button type="button" onclick="location.reload()">새로고침</button></div></main>`;return false;});
})();
